        return self.std_deduction
    reduction = (income - self.phase_out_start) // 1000 * 1000
    return max(self.std_deduction - reduction, 0)

def tax_owed(self, income):
    deduction = self.adjusted_deduction(income)
    taxable_income = max(income - deduction, 0)
    return self.compute_tax(taxable_income)

